/* From Uiverse.io by mrhyddenn - Tags: button */
.__UIV_SCOPE__ .icon-btn {
  width: 50px;
  height: 50px;
  border: 1px solid #cdcdcd;
  background: white;
  border-radius: 25px;
  overflow: hidden;
  position: relative;
  transition: width 0.2s ease-in-out;
  font-weight: 500;
  font-family: inherit;
}

.__UIV_SCOPE__ .add-btn:hover {
  width: 120px;
}

.__UIV_SCOPE__ .add-btn::before,
.__UIV_SCOPE__ .add-btn::after {
  transition: width 0.2s ease-in-out, border-radius 0.2s ease-in-out;
  content: "";
  position: absolute;
  height: 4px;
  width: 10px;
  top: calc(50% - 2px);
  background: seagreen;
}

.__UIV_SCOPE__ .add-btn::after {
  right: 14px;
  overflow: hidden;
  border-top-right-radius: 2px;
  border-bottom-right-radius: 2px;
}

.__UIV_SCOPE__ .add-btn::before {
  left: 14px;
  border-top-left-radius: 2px;
  border-bottom-left-radius: 2px;
}

.__UIV_SCOPE__ .icon-btn:focus {
  outline: none;
}

.__UIV_SCOPE__ .btn-txt {
  opacity: 0;
  transition: opacity 0.2s;
}

.__UIV_SCOPE__ .add-btn:hover::before,
.__UIV_SCOPE__ .add-btn:hover::after {
  width: 4px;
  border-radius: 2px;
}

.__UIV_SCOPE__ .add-btn:hover .btn-txt {
  opacity: 1;
}

.__UIV_SCOPE__ .add-icon::after,
.__UIV_SCOPE__ .add-icon::before {
  transition: all 0.2s ease-in-out;
  content: "";
  position: absolute;
  height: 20px;
  width: 2px;
  top: calc(50% - 10px);
  background: seagreen;
  overflow: hidden;
}

.__UIV_SCOPE__ .add-icon::before {
  left: 22px;
  border-top-left-radius: 2px;
  border-bottom-left-radius: 2px;
}

.__UIV_SCOPE__ .add-icon::after {
  right: 22px;
  border-top-right-radius: 2px;
  border-bottom-right-radius: 2px;
}

.__UIV_SCOPE__ .add-btn:hover .add-icon::before {
  left: 15px;
  height: 4px;
  top: calc(50% - 2px);
}

.__UIV_SCOPE__ .add-btn:hover .add-icon::after {
  right: 15px;
  height: 4px;
  top: calc(50% - 2px);
}
